7	import type { Config } from '../config/config.js';
8	import type {
9	  RoutingContext,
10	  RoutingDecision,
11	  TerminalStrategy,
12	} from './routingStrategy.js';
13	import { DefaultStrategy } from './strategies/defaultStrategy.js';
14	import { ClassifierStrategy } from './strategies/classifierStrategy.js';
15	import { NumericalClassifierStrategy } from './strategies/numericalClassifierStrategy.js';
16	import { CompositeStrategy } from './strategies/compositeStrategy.js';
17	import { FallbackStrategy } from './strategies/fallbackStrategy.js';
18	import { OverrideStrategy } from './strategies/overrideStrategy.js';
19	
20	import { logModelRouting } from '../telemetry/loggers.js';
21	import { ModelRoutingEvent } from '../telemetry/types.js';
22	import { debugLogger } from '../utils/debugLogger.js';
23	
24	/**
25	 * A centralized service for making model routing decisions.
26	 */
27	export class ModelRouterService {
28	  private config: Config;
29	  private strategy: TerminalStrategy;
30	
31	  constructor(config: Config) {
32	    this.config = config;
33	    this.strategy = this.initializeDefaultStrategy();
34	  }
35	
36	  private initializeDefaultStrategy(): TerminalStrategy {
37	    // Initialize the composite strategy with the desired priority order.
38	    // The strategies are ordered in order of highest priority.
39	    return new CompositeStrategy(
40	      [
41	        new FallbackStrategy(),
42	        new OverrideStrategy(),
43	        new ClassifierStrategy(),
44	        new NumericalClassifierStrategy(),
45	        new DefaultStrategy(),
46	      ],
47	      'agent-router',
48	    );
49	  }
50	
51	  /**
52	   * Determines which model to use for a given request context.
53	   *
54	   * @param context The full context of the request.
55	   * @returns A promise that resolves to a RoutingDecision.
56	   */
57	  async route(context: RoutingContext): Promise<RoutingDecision> {
58	    const startTime = Date.now();
59	    let decision: RoutingDecision;
60	
61	    const [enableNumericalRouting, thresholdValue] = await Promise.all([
62	      this.config.getNumericalRoutingEnabled(),
63	      this.config.getClassifierThreshold(),
64	    ]);
65	    const classifierThreshold =
66	      thresholdValue !== undefined ? String(thresholdValue) : undefined;
67	
68	    let failed = false;
69	    let error_message: string | undefined;
70	
71	    try {
72	      decision = await this.strategy.route(
73	        context,
74	        this.config,
75	        this.config.getBaseLlmClient(),
76	      );
77	
78	      debugLogger.debug(
79	        `[Routing] Selected model: ${decision.model} (Source: ${decision.metadata.source}, Latency: ${decision.metadata.latencyMs}ms)\n\t[Routing] Reasoning: ${decision.metadata.reasoning}`,
80	      );
81	    } catch (e) {
82	      failed = true;
83	      error_message = e instanceof Error ? e.message : String(e);
84	      // Create a fallback decision for logging purposes
85	      // We do not actually route here. This should never happen so we should
86	      // fail loudly to catch any issues where this happens.
87	      decision = {
88	        model: this.config.getModel(),
89	        metadata: {
90	          source: 'router-exception',
91	          latencyMs: Date.now() - startTime,
92	          reasoning: 'An exception occurred during routing.',
93	          error: error_message,
94	        },
95	      };
96	
97	      debugLogger.debug(
98	        `[Routing] Exception during routing: ${error_message}\n\tFallback model: ${decision.model} (Source: ${decision.metadata.source})`,
99	      );
100	    } finally {
101	      const event = new ModelRoutingEvent(
102	        decision!.model,
103	        decision!.metadata.source,
104	        decision!.metadata.latencyMs,
105	        decision!.metadata.reasoning,
106	        failed,
107	        error_message,
108	        enableNumericalRouting,
109	        classifierThreshold,
110	      );
111	      logModelRouting(this.config, event);
112	    }
113	
114	    return decision;
115	  }
116	}
