7	import type { Content, PartListUnion } from '@google/genai';
8	import type { BaseLlmClient } from '../core/baseLlmClient.js';
9	import type { Config } from '../config/config.js';
10	
11	/**
12	 * The output of a routing decision. It specifies which model to use and why.
13	 */
14	export interface RoutingDecision {
15	  /** The model identifier string to use for the next API call (e.g., 'gemini-2.5-pro'). */
16	  model: string;
17	  /**
18	   * Metadata about the routing decision for logging purposes.
19	   */
20	  metadata: {
21	    source: string;
22	    latencyMs: number;
23	    reasoning: string;
24	    error?: string;
25	  };
26	}
27	
28	/**
29	 * The context provided to the router for making a decision.
30	 */
31	export interface RoutingContext {
32	  /** The full history of the conversation. */
33	  history: Content[];
34	  /** The immediate request parts to be processed. */
35	  request: PartListUnion;
36	  /** An abort signal to cancel an LLM call during routing. */
37	  signal: AbortSignal;
38	  /** The model string requested for this turn, if any. */
39	  requestedModel?: string;
40	}
41	
42	/**
43	 * The core interface that all routing strategies must implement.
44	 * Strategies implementing this interface may decline a request by returning null.
45	 */
46	export interface RoutingStrategy {
47	  /** The name of the strategy (e.g., 'fallback', 'override', 'composite'). */
48	  readonly name: string;
49	
50	  /**
51	   * Determines which model to use for a given request context.
52	   * @param context The full context of the request.
53	   * @param config The current configuration.
54	   * @param client A reference to the GeminiClient, allowing the strategy to make its own API calls if needed.
55	   * @returns A promise that resolves to a RoutingDecision, or null if the strategy is not applicable.
56	   */
57	  route(
58	    context: RoutingContext,
59	    config: Config,
60	    baseLlmClient: BaseLlmClient,
61	  ): Promise<RoutingDecision | null>;
62	}
63	
64	/**
65	 * A strategy that is guaranteed to return a decision. It must not return null.
66	 * This is used to ensure that a composite chain always terminates.
67	 */
68	export interface TerminalStrategy extends RoutingStrategy {
69	  /**
70	   * Determines which model to use for a given request context.
71	   * @returns A promise that resolves to a RoutingDecision.
72	   */
73	  route(
74	    context: RoutingContext,
75	    config: Config,
76	    baseLlmClient: BaseLlmClient,
77	  ): Promise<RoutingDecision>;
78	}
