1	/**
2	 * @license
3	 * Copyright 2025 Google LLC
4	 * SPDX-License-Identifier: Apache-2.0
5	 */
6	
7	export const PREVIEW_GEMINI_MODEL = 'gemini-3-pro-preview';
8	export const PREVIEW_GEMINI_3_1_MODEL = 'gemini-3.1-pro-preview';
9	export const PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL =
10	  'gemini-3.1-pro-preview-customtools';
11	export const PREVIEW_GEMINI_FLASH_MODEL = 'gemini-3-flash-preview';
12	export const DEFAULT_GEMINI_MODEL = 'gemini-2.5-pro';
13	export const DEFAULT_GEMINI_FLASH_MODEL = 'gemini-2.5-flash';
14	export const DEFAULT_GEMINI_FLASH_LITE_MODEL = 'gemini-2.5-flash-lite';
15	
16	export const VALID_GEMINI_MODELS = new Set([
17	  PREVIEW_GEMINI_MODEL,
18	  PREVIEW_GEMINI_3_1_MODEL,
19	  PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL,
20	  PREVIEW_GEMINI_FLASH_MODEL,
21	  DEFAULT_GEMINI_MODEL,
22	  DEFAULT_GEMINI_FLASH_MODEL,
23	  DEFAULT_GEMINI_FLASH_LITE_MODEL,
24	]);
25	
26	export const PREVIEW_GEMINI_MODEL_AUTO = 'auto-gemini-3';
27	export const DEFAULT_GEMINI_MODEL_AUTO = 'auto-gemini-2.5';
28	
29	// Model aliases for user convenience.
30	export const GEMINI_MODEL_ALIAS_AUTO = 'auto';
31	export const GEMINI_MODEL_ALIAS_PRO = 'pro';
32	export const GEMINI_MODEL_ALIAS_FLASH = 'flash';
33	export const GEMINI_MODEL_ALIAS_FLASH_LITE = 'flash-lite';
34	
35	export const DEFAULT_GEMINI_EMBEDDING_MODEL = 'gemini-embedding-001';
36	
37	// Cap the thinking at 8192 to prevent run-away thinking loops.
38	export const DEFAULT_THINKING_MODE = 8192;
39	
40	/**
41	 * Resolves the requested model alias (e.g., 'auto-gemini-3', 'pro', 'flash', 'flash-lite')
42	 * to a concrete model name.
43	 *
44	 * @param requestedModel The model alias or concrete model name requested by the user.
45	 * @param useGemini3_1 Whether to use Gemini 3.1 Pro Preview for auto/pro aliases.
46	 * @returns The resolved concrete model name.
47	 */
48	export function resolveModel(
49	  requestedModel: string,
50	  useGemini3_1: boolean = false,
51	  useCustomToolModel: boolean = false,
52	): string {
53	  switch (requestedModel) {
54	    case PREVIEW_GEMINI_MODEL:
55	    case PREVIEW_GEMINI_MODEL_AUTO:
56	    case GEMINI_MODEL_ALIAS_AUTO:
57	    case GEMINI_MODEL_ALIAS_PRO: {
58	      if (useGemini3_1) {
59	        return useCustomToolModel
60	          ? PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL
61	          : PREVIEW_GEMINI_3_1_MODEL;
62	      }
63	      return PREVIEW_GEMINI_MODEL;
64	    }
65	    case DEFAULT_GEMINI_MODEL_AUTO: {
66	      return DEFAULT_GEMINI_MODEL;
67	    }
68	    case GEMINI_MODEL_ALIAS_FLASH: {
69	      return PREVIEW_GEMINI_FLASH_MODEL;
70	    }
71	    case GEMINI_MODEL_ALIAS_FLASH_LITE: {
72	      return DEFAULT_GEMINI_FLASH_LITE_MODEL;
73	    }
74	    default: {
75	      return requestedModel;
76	    }
77	  }
78	}
79	
80	/**
81	 * Resolves the appropriate model based on the classifier's decision.
82	 *
83	 * @param requestedModel The current requested model (e.g. auto-gemini-2.5).
84	 * @param modelAlias The alias selected by the classifier ('flash' or 'pro').
85	 * @returns The resolved concrete model name.
86	 */
87	export function resolveClassifierModel(
88	  requestedModel: string,
89	  modelAlias: string,
90	  useGemini3_1: boolean = false,
91	  useCustomToolModel: boolean = false,
92	): string {
93	  if (modelAlias === GEMINI_MODEL_ALIAS_FLASH) {
94	    if (
95	      requestedModel === DEFAULT_GEMINI_MODEL_AUTO ||
96	      requestedModel === DEFAULT_GEMINI_MODEL
97	    ) {
98	      return DEFAULT_GEMINI_FLASH_MODEL;
99	    }
100	    if (
101	      requestedModel === PREVIEW_GEMINI_MODEL_AUTO ||
102	      requestedModel === PREVIEW_GEMINI_MODEL
103	    ) {
104	      return PREVIEW_GEMINI_FLASH_MODEL;
105	    }
106	    return resolveModel(GEMINI_MODEL_ALIAS_FLASH);
107	  }
108	  return resolveModel(requestedModel, useGemini3_1, useCustomToolModel);
109	}
110	export function getDisplayString(model: string) {
111	  switch (model) {
112	    case PREVIEW_GEMINI_MODEL_AUTO:
113	      return 'Auto (Gemini 3)';
114	    case DEFAULT_GEMINI_MODEL_AUTO:
115	      return 'Auto (Gemini 2.5)';
116	    case GEMINI_MODEL_ALIAS_PRO:
117	      return PREVIEW_GEMINI_MODEL;
118	    case GEMINI_MODEL_ALIAS_FLASH:
119	      return PREVIEW_GEMINI_FLASH_MODEL;
120	    case PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL:
121	      return PREVIEW_GEMINI_3_1_MODEL;
122	    default:
123	      return model;
124	  }
125	}
126	
127	/**
128	 * Checks if the model is a preview model.
129	 *
130	 * @param model The model name to check.
131	 * @returns True if the model is a preview model.
132	 */
133	export function isPreviewModel(model: string): boolean {
134	  return (
135	    model === PREVIEW_GEMINI_MODEL ||
136	    model === PREVIEW_GEMINI_3_1_MODEL ||
137	    model === PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL ||
138	    model === PREVIEW_GEMINI_FLASH_MODEL ||
139	    model === PREVIEW_GEMINI_MODEL_AUTO
140	  );
141	}
142	
143	/**
144	 * Checks if the model is a Pro model.
145	 *
146	 * @param model The model name to check.
147	 * @returns True if the model is a Pro model.
148	 */
149	export function isProModel(model: string): boolean {
150	  return model.toLowerCase().includes('pro');
151	}
152	
153	/**
154	 * Checks if the model is a Gemini 3 model.
155	 *
156	 * @param model The model name to check.
157	 * @returns True if the model is a Gemini 3 model.
158	 */
159	export function isGemini3Model(model: string): boolean {
160	  const resolved = resolveModel(model);
161	  return /^gemini-3(\.|-|$)/.test(resolved);
162	}
163	
164	/**
165	 * Checks if the model is a Gemini 2.x model.
166	 *
167	 * @param model The model name to check.
168	 * @returns True if the model is a Gemini-2.x model.
169	 */
170	export function isGemini2Model(model: string): boolean {
171	  return /^gemini-2(\.|$)/.test(model);
172	}
173	
174	/**
175	 * Checks if the model is a "custom" model (not Gemini branded).
176	 *
177	 * @param model The model name to check.
178	 * @returns True if the model is not a Gemini branded model.
179	 */
180	export function isCustomModel(model: string): boolean {
181	  const resolved = resolveModel(model);
182	  return !resolved.startsWith('gemini-');
183	}
184	
185	/**
186	 * Checks if the model should be treated as a modern model.
187	 * This includes Gemini 3 models and any custom models.
188	 *
189	 * @param model The model name to check.
190	 * @returns True if the model supports modern features like thoughts.
191	 */
192	export function supportsModernFeatures(model: string): boolean {
193	  if (isGemini3Model(model)) return true;
194	  return isCustomModel(model);
195	}
196	
197	/**
198	 * Checks if the model is an auto model.
199	 *
200	 * @param model The model name to check.
201	 * @returns True if the model is an auto model.
202	 */
203	export function isAutoModel(model: string): boolean {
204	  return (
205	    model === GEMINI_MODEL_ALIAS_AUTO ||
206	    model === PREVIEW_GEMINI_MODEL_AUTO ||
207	    model === DEFAULT_GEMINI_MODEL_AUTO
208	  );
209	}
210	
211	/**
212	 * Checks if the model supports multimodal function responses (multimodal data nested within function response).
213	 * This is supported in Gemini 3.
214	 *
215	 * @param model The model name to check.
216	 * @returns True if the model supports multimodal function responses.
217	 */
218	export function supportsMultimodalFunctionResponse(model: string): boolean {
219	  return model.startsWith('gemini-3-');
220	}
221	
222	/**
223	 * Checks if the given model is considered active based on the current configuration.
224	 *
225	 * @param model The model name to check.
226	 * @param useGemini3_1 Whether Gemini 3.1 Pro Preview is enabled.
227	 * @returns True if the model is active.
228	 */
229	export function isActiveModel(
